INSERT IGNORE INTO `portfolios` (`id`, `title`, `category`, `client`, `type`, `project_date`, `summary`, `site_url`, `thumbnail`, `hero_image`, `detail_image`, `sort_order`, `is_visible`, `created_at`, `updated_at`) VALUES (1,'SWEATIE','branding','SWEATIE','Branding, UI/UX Design, Responsive Web','2025.07 ~ 2025.10','SWEATIE는 러닝 메이트와 함께 목표에 도전하고, 기록과 성취를 공유하는 러닝 플랫폼 브랜드 웹사이트입니다. \n러닝 메이트 매칭부터 챌린지, 기록 관리, 커뮤니티까지 주요 콘텐츠를 하나의 흐름으로 연결하고, 역동적인 비주얼과 인터랙션을 활용해 브랜드의 활기찬 에너지를 표현했습니다.','https://r00neyj.github.io/Sweatie_Brand_Web/','/aseets/imgs/portfolio-sub/SWEATIE.png','/aseets/imgs/portfolio-sub/sweatie-hero.png','/aseets/imgs/portfolio-sub/sweatie-pro.png',1,1,'2026-10-12 22:14:08','2026-10-20 15:35:47');
INSERT IGNORE INTO `portfolios` (`id`, `title`, `category`, `client`, `type`, `project_date`, `summary`, `site_url`, `thumbnail`, `hero_image`, `detail_image`, `sort_order`, `is_visible`, `created_at`, `updated_at`) VALUES (2,'CJ 올리브영','uiux','CJ 올리브영','Web Redesign, UI/UX Design, Web Publishing','2025.12 ~ 2026.02','올리브영은 사용자가 원하는 상품과 정보를 쉽고 빠르게 탐색할 수 있도록 리디자인한 프로젝트입니다. \n기존의 복잡한 콘텐츠를 카테고리별로 재구성하고, 충분한 여백과 명확한 정보 위계를 통해 가독성을 높였습니다.','https://lee-geon-gyu.github.io/OY_Redesign/','/aseets/imgs/portfolio-sub/oy.png','/aseets/imgs/portfolio-sub/oy-hero.png','/aseets/imgs/portfolio-sub/oy-pro.png',10,1,'2026-10-12 22:14:08','2026-10-20 16:21:12');
INSERT IGNORE INTO `portfolios` (`id`, `title`, `category`, `client`, `type`, `project_date`, `summary`, `site_url`, `thumbnail`, `hero_image`, `detail_image`, `sort_order`, `is_visible`, `created_at`, `updated_at`) VALUES (3,'쿠무','branding','Kumu','Branding, UI/UX Design, Responsive Web','2025.10 ~ 2025.12','쿠무는 사람과 반려견이 함께 식사와 디저트를 즐기며 특별한 시간을 만들어가는 반려동물 동반 카페·베이커리 브랜드입니다.\n분산된 메뉴와 이용 정보, 브랜드 콘텐츠를 하나의 웹사이트 안에서 연결하고, 계절에 따라 변화하는 메뉴와 클래스, 이벤트를 자연스럽게 탐색할 수 있도록 반응형 웹사이트를 설계했습니다.','https://tnfh23-web.github.io/kumu/','/aseets/imgs/portfolio-sub/kumu.png','/aseets/imgs/portfolio-sub/back.png','/aseets/imgs/portfolio-sub/kumu-pro.png',5,1,'2026-10-12 22:14:08','2026-10-19 23:08:02');
INSERT IGNORE INTO `portfolios` (`id`, `title`, `category`, `client`, `type`, `project_date`, `summary`, `site_url`, `thumbnail`, `hero_image`, `detail_image`, `sort_order`, `is_visible`, `created_at`, `updated_at`) VALUES (4,'AFTERIMAGE','front','AFTERIMAGE','3D Web, Interactive Web','2026.09 ~ 2026.10','AFTERIMAGE 작품을 단순히 화면으로 감상하는 것을 넘어, 사용자가 직접 공간을 탐색하며 전시를 경험할 수 있도록 구성한 3D 웹사이트입니다. \n자유로운 이동과 시점 변화를 통해 작품을 다양한 각도에서 감상할 수 있도록 하고, 사용자의 움직임에 따라 새로운 장면이 펼쳐지는 몰입형 전시 경험을 표현했습니다.','https://tnfh23-web.github.io/afterimage/','/aseets/imgs/portfolio-sub/afterimage.webp','/aseets/imgs/portfolio-sub/afterimage-hero.png','/aseets/imgs/portfolio-sub/afterimage-pro.png',4,1,'2026-10-12 22:14:08','2026-10-20 00:22:03');
INSERT IGNORE INTO `portfolios` (`id`, `title`, `category`, `client`, `type`, `project_date`, `summary`, `site_url`, `thumbnail`, `hero_image`, `detail_image`, `sort_order`, `is_visible`, `created_at`, `updated_at`) VALUES (5,'Rawdoc','mvp','Rawdoc','Web Application, Markdown Editor','2026.09 ~ 2026.10','Rawdoc은 문서 작성과 정보 관리를 하나의 공간에서 해결할 수 있도록 만든 서비스입니다.\n마크다운 편집과 폴더 구조, 문서 간 연결 기능을 통해 정보를 체계적으로 정리할 수 있도록 구성했습니다.','https://rawdoc.app','/aseets/imgs/portfolio-sub/rawdoc.png','/aseets/imgs/portfolio-sub/rawdoc-hero.png','/aseets/imgs/portfolio-sub/rawdoc-pro.png',2,1,'2026-10-12 22:14:08','2026-10-20 00:36:02');
INSERT IGNORE INTO `portfolios` (`id`, `title`, `category`, `client`, `type`, `project_date`, `summary`, `site_url`, `thumbnail`, `hero_image`, `detail_image`, `sort_order`, `is_visible`, `created_at`, `updated_at`) VALUES (6,'EAT-GO','uiux','EAT-GO','App Branding, UI/UX Design, App Design','2025.10 ~ 2025.11','잇고는 기존 식단 관리 앱의 반복적인 수동 입력과 기록 피로도를 개선하기 위해 기획한 서비스입니다. \n카드 결제 내역 기반의 자동 기록으로 사용자의 부담을 줄이고, 직관적인 대시보드와 캐릭터 성장 및 보상 시스템을 통해 꾸준히 식습관을 관리할 수 있도록 설계했습니다.','https://r00neyj.github.io/Eatgo_Process/','/aseets/imgs/portfolio-sub/eatgo.png','/aseets/imgs/portfolio-sub/eatgo-hero-uploaded.png','/aseets/imgs/portfolio-sub/eatgo-pro.png',3,1,'2026-10-12 22:14:08','2026-10-19 23:34:44');
INSERT IGNORE INTO `portfolios` (`id`, `title`, `category`, `client`, `type`, `project_date`, `summary`, `site_url`, `thumbnail`, `hero_image`, `detail_image`, `sort_order`, `is_visible`, `created_at`, `updated_at`) VALUES (7,'Modoo','front','Modoo','Web Redesign, Interactive Web','2026.04 ~ 2026.06','모두는 기업의 핵심 역량과 프로젝트 경험을 시각적으로 전달하는 데 초점을 맞춘 웹사이트입니다. \n회사 소개부터 포트폴리오, 핵심 역량, 제작 프로세스까지 콘텐츠를 구성하고, GSAP을 활용한 스크롤 애니메이션과 화면 전환 효과를 적용해 사용자가 콘텐츠를 자연스럽게 탐색할 수 있도록 구현했습니다.','https://tnfh23-web.github.io/react-modoo/','/aseets/imgs/portfolio-sub/modoo.png','/aseets/imgs/portfolio-sub/modoo-hero.png','/aseets/imgs/portfolio-sub/modoo-pro.png',6,1,'2026-10-19 23:44:10','2026-10-19 23:49:53');
INSERT IGNORE INTO `portfolios` (`id`, `title`, `category`, `client`, `type`, `project_date`, `summary`, `site_url`, `thumbnail`, `hero_image`, `detail_image`, `sort_order`, `is_visible`, `created_at`, `updated_at`) VALUES (8,'reflow','mvp','reflow','Web Application, UI/UX Design','2026.9 ~ 2026.10','리플로우는 흩어진 웹 디자인 레퍼런스를 한곳에 모아 관리할 수 있도록 만든 서비스입니다. \n메모와 태그를 활용해 자료를 저장하고, 검색과 분류 기능으로 필요한 레퍼런스를 쉽게 찾을 수 있도록 구성했습니다.','https://reflow.tnfh23.workers.dev/','/aseets/imgs/portfolio-sub/reflow.png','/aseets/imgs/portfolio-sub/reflow-hero.png','/aseets/imgs/portfolio-sub/reflow-pro.png',7,1,'2026-10-19 23:57:31','2026-10-19 23:59:59');
INSERT IGNORE INTO `portfolios` (`id`, `title`, `category`, `client`, `type`, `project_date`, `summary`, `site_url`, `thumbnail`, `hero_image`, `detail_image`, `sort_order`, `is_visible`, `created_at`, `updated_at`) VALUES (9,'DIVE','front','DIVE','Branding, UI/UX Design, Interactive Web','2026.07 ~ 2026.08','다이브는 디자인과 웹 제작에 필요한 정보를 한곳에서 탐색하고 학습할 수 있도록 만든 플랫폼입니다. \n다양한 콘텐츠를 주제별로 분류해 직관적인 레이아웃과 자연스러운 화면 전환을 통해 처음 접하는 사용자도 편리하게 이용할 수 있도록 설계했습니다.','https://lee-geon-gyu.github.io/DIVE_Web_React_Ts/','/aseets/imgs/portfolio-sub/dive.png','/aseets/imgs/portfolio-sub/dive-hero.png','/aseets/imgs/portfolio-sub/dive-pro.png',8,1,'2026-10-20 15:54:02','2026-10-20 15:56:07');
INSERT IGNORE INTO `portfolios` (`id`, `title`, `category`, `client`, `type`, `project_date`, `summary`, `site_url`, `thumbnail`, `hero_image`, `detail_image`, `sort_order`, `is_visible`, `created_at`, `updated_at`) VALUES (10,'JW중외제약','uiux','JW중외제약','Web Redesign, UI/UX Design, Web Publishing','2025.10 – 2025.12','JW중외제약은 기업의 핵심 정보와 연구 역량을 사용자가 쉽고 명확하게 이해할 수 있도록 리디자인한 프로젝트입니다. \n콘텐츠의 우선순위를 재정리하고, 직관적인 내비게이션과 일관된 디자인 시스템을 통해 정보 탐색의 편의성을 높였습니다.','https://lee-geon-gyu.github.io/JW_Redesign/','/aseets/imgs/portfolio-sub/jw.png','/aseets/imgs/portfolio-sub/jw-hero.png','/aseets/imgs/portfolio-sub/jw-pro.png',9,1,'2026-10-20 16:20:36','2026-10-20 16:21:12');

